CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(40) NOT NULL CHECK(role IN ('Admin','CRM Manager','Policy Officer','Finance Manager','Customer')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY,name VARCHAR(160) UNIQUE NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id BIGSERIAL PRIMARY KEY,name VARCHAR(160) UNIQUE NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,phone VARCHAR(40),status VARCHAR(30) NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','At Risk','Lost','Retained')),preferences JSONB DEFAULT '{}',lifetime_value NUMERIC(14,2) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customer_interactions (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,channel VARCHAR(40) NOT NULL,interaction_type VARCHAR(80) NOT NULL,notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS smart_devices (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,device_type VARCHAR(80) NOT NULL,status VARCHAR(30) DEFAULT 'Online',health_score INT DEFAULT 100 CHECK(health_score BETWEEN 0 AND 100),last_seen TIMESTAMPTZ,telemetry JSONB DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customer_behaviors (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,action VARCHAR(100) NOT NULL,product_or_service VARCHAR(120),value NUMERIC(14,2) DEFAULT 0,metadata JSONB DEFAULT '{}',recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS policies (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),policy_number VARCHAR(80) UNIQUE NOT NULL,status VARCHAR(30) DEFAULT 'Active',premium NUMERIC(14,2) NOT NULL,risk_score NUMERIC(5,2) DEFAULT 50,start_date DATE NOT NULL,end_date DATE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS policy_payments (id BIGSERIAL PRIMARY KEY,policy_id BIGINT REFERENCES policies(id) ON DELETE CASCADE,amount NUMERIC(14,2) NOT NULL,payment_date DATE DEFAULT CURRENT_DATE,status VARCHAR(30) DEFAULT 'Paid',reference VARCHAR(100));
CREATE TABLE IF NOT EXISTS revenue (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE SET NULL,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,service_id BIGINT REFERENCES services(id) ON DELETE SET NULL,amount NUMERIC(14,2) NOT NULL,source VARCHAR(80) NOT NULL,recorded_at DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS costs (id BIGSERIAL PRIMARY KEY,category VARCHAR(80) NOT NULL,amount NUMERIC(14,2) NOT NULL,description TEXT,recorded_at DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS personnel_costs (id BIGSERIAL PRIMARY KEY,department VARCHAR(100) NOT NULL,amount NUMERIC(14,2) NOT NULL,recorded_at DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS maintenance_costs (id BIGSERIAL PRIMARY KEY,application_name VARCHAR(140) NOT NULL,amount NUMERIC(14,2) NOT NULL,recorded_at DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS financial_transactions (id BIGSERIAL PRIMARY KEY,type VARCHAR(30) NOT NULL CHECK(type IN ('Revenue','Cost','Payment','Refund')),amount NUMERIC(14,2) NOT NULL,reference VARCHAR(120),description TEXT,transaction_date DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS customer_satisfaction (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,score NUMERIC(3,2) CHECK(score BETWEEN 1 AND 5),feedback TEXT,recorded_at DATE DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id) ON DELETE CASCADE,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,type VARCHAR(40) DEFAULT 'Info',read_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_customers_status ON customers(status); CREATE INDEX IF NOT EXISTS idx_interactions_customer ON customer_interactions(customer_id); CREATE INDEX IF NOT EXISTS idx_devices_customer ON smart_devices(customer_id); CREATE INDEX IF NOT EXISTS idx_behaviors_customer ON customer_behaviors(customer_id); CREATE INDEX IF NOT EXISTS idx_policies_customer ON policies(customer_id); CREATE INDEX IF NOT EXISTS idx_revenue_date ON revenue(recorded_at); CREATE INDEX IF NOT EXISTS idx_costs_date ON costs(recorded_at);